from scrapy.conf import settings

class Scheduler(object):

    def __init__(self):
        self.pending_requests = {}
        self.dfo = settings['SCHEDULER_ORDER'].upper() == 'DFO'
        self.dupefilter = load_object(settings['DUPEFILTER_CLASS'])()

