def getwithbase(self, name: _SettingsKey) -> BaseSettings:
        """Get a composition of a dictionary-like setting and its `_BASE`
        counterpart.

        :param name: name of the dictionary-like setting
        :type name: str
        """
        if not isinstance(name, str):
            raise ValueError(f"Base setting key must be a string, got {name}")

        normalized_keys = {}
        obj_keys = set()

        def track_loaded_key(k: Any) -> None:
            if k not in obj_keys:
                obj_keys.add(k)
                return
            logger.warning(
                f"Setting {name} contains multiple keys that refer to the "
                f"same object: {global_object_name(k)}. Only the last one will "
                f"be kept."
            )

        def normalize_key(key: Any) -> str:
            try:
                loaded_key = load_object(key)
            except (AttributeError, TypeError, ValueError):
                loaded_key = key
            else:
                import_path = global_object_name(loaded_key)
                normalized_keys[import_path] = key
                key = import_path
            track_loaded_key(loaded_key)
            return key

        def restore_key(k: str) -> Any:
            return normalized_keys.get(k, k)

        result = dict(self[name + "_BASE"] or {})
        override = {normalize_key(k): v for k, v in (self[name] or {}).items()}
        result.update(override)
        return BaseSettings(
            {restore_key(k): v for k, v in result.items() if v is not None}
        )

def next_request(self, spider, now=False):
        """Scrape the next request for the domain passed.

        The next request to be scraped is retrieved from the scheduler and
        requested from the downloader.

        The domain is closed if there are no more pages to scrape.
        """
        if self.paused:
            return reactor.callLater(5, self.next_request, spider)

        # call next_request in next reactor loop by default
        if not now:
            return reactor.callLater(0, self.next_request, spider, now=True)

        domain = spider.domain_name

        if not self.running or \
                self.domain_is_closed(domain) or \
                self.downloader.sites[domain].needs_backout():
            return

        # Next pending request from scheduler
        request, deferred = self.scheduler.next_request(domain)
        if request:
            mustbe_deferred(self.download, request, spider).chainDeferred(deferred)
        elif self.domain_is_idle(domain):
            self._domain_idle(domain)

